//! Riced Wayland shell library and generated-shell entry points.
//!
//! The default `riced` binary is a thin wrapper around [`run_default`]. A
//! project shell generated by `riced build` links the same library and calls
//! [`run_project`] after registering its compiled-in extensions.
use iced_exwlshell::daemon;
use std::path::PathBuf;
use wayland_client::Connection;

mod cli;
mod config;
mod framework;
mod icons;
mod lua;
mod notify;
mod services;
mod shared;
mod shell;
mod theme;
mod theme_gen;
mod tray;
mod ui;
mod wallpaper;

use cli::commands::{run_apply_templates, run_generate_theme};
use iced_exwlshell::settings::Settings;
use shell::Plots;

/// Re-exported registry type for generated shell entry points.
pub use riced_extension_sdk::Registry;
/// Process service registration types for generated shell entry points.
pub use riced_extension_sdk::{Descriptor, process::ProcessExtension};

/// Host topics reserved from extension services.
///
/// Generated shells pass this to each extension's `register` function so
/// extension namespaces cannot shadow built-in services.
pub fn builtin_service_topics() -> &'static [&'static str] {
    framework::extensions::BUILTIN_TOPICS
}

/// Run the shell with the default compiled-in extensions.
pub fn run_default() -> Result<(), Box<dyn std::error::Error>> {
    run(framework::extensions::default_registry()?)
}

/// Run the shell with an explicit extension registry.
pub fn run(registry: Registry) -> Result<(), Box<dyn std::error::Error>> {
    run_with(registry, None)
}

/// Run the shell with an explicit registry and a default project directory.
///
/// `-p`/`-c` still override `project_root`. Generated shells pass the project
/// directory captured at build time so the binary works without extra flags.
pub fn run_project(
    registry: Registry,
    project_root: impl Into<PathBuf>,
) -> Result<(), Box<dyn std::error::Error>> {
    run_with(registry, Some(project_root.into()))
}

fn run_with(
    registry: Registry,
    default_project_root: Option<PathBuf>,
) -> Result<(), Box<dyn std::error::Error>> {
    framework::extensions::install(registry);
    struct Shutdown;
    impl Drop for Shutdown {
        fn drop(&mut self) {
            if let Ok(registry) = framework::extensions::registry() {
                registry.shutdown();
            }
        }
    }
    let _shutdown = Shutdown;
    let cli = cli::parse();
    let project_root = match cli.project_root()? {
        Some(root) => Some(root),
        None => default_project_root,
    };
    if let Some(root) = project_root {
        config::set_project_root(root)?;
    }
    let command = cli.command;
    if matches!(
        &command,
        None | Some(cli::Commands::GenerateTheme { .. } | cli::Commands::ApplyTemplates { .. })
    ) {
        config::layout::migrate(&config::project_dir())?;
    }
    if command.is_some() {
        // CLI commands never evaluate the shell entry; keep logging at the
        // environment/default level.
        init_tracing(None);
    }
    if let Some(cli::Commands::LuaDemo { script }) = command {
        lua::demo::run(script)?;
        return Ok(());
    }

    match command {
        Some(cli::Commands::Ipc { command, args }) => {
            cli::queue_ipc(command, args)?;
            Ok(())
        }
        Some(cli::Commands::Init { repair }) => {
            let mode = if repair {
                config::initialize::Mode::Repair
            } else {
                config::initialize::Mode::Startup
            };
            let outcome = config::initialize::selected(mode)?;
            println!(
                "riced: frontend {outcome:?} at {}",
                config::project_dir().join("shell.lua").display()
            );
            Ok(())
        }
        Some(cli::Commands::LuaDemo { .. }) => unreachable!("Lua demo handled above"),
        Some(cli::Commands::GenerateTheme {
            variant,
            set,
            templates,
            no_templates,
        }) => run_generate_theme(variant, set, templates, no_templates).map_err(Into::into),
        Some(cli::Commands::ApplyTemplates { templates, name }) => {
            run_apply_templates(templates, name).map_err(Into::into)
        }
        Some(cli::Commands::Build {
            release,
            locked,
            framework,
            target_dir,
        }) => cli::build::run(cli::build::Options {
            release,
            locked,
            framework,
            target_dir,
        }),
        Some(cli::Commands::Extension(command)) => cli::extension::run(match command {
            cli::ExtensionCommand::Build {
                name,
                release,
                locked,
            } => cli::extension::Options {
                name,
                release,
                locked,
                shell: false,
                framework: None,
                target_dir: None,
            },
            cli::ExtensionCommand::Update {
                name,
                release,
                locked,
                framework,
                target_dir,
            } => cli::extension::Options {
                name,
                release,
                locked,
                shell: true,
                framework,
                target_dir,
            },
        }),
        // No subcommand: run the shell daemon.
        None => {
            if config::project_root().is_none() {
                config::initialize::selected(config::initialize::Mode::Startup)?;
            }
            run_daemon()
        }
    }
}

fn run_daemon() -> Result<(), Box<dyn std::error::Error>> {
    let runtime = shell_runtime()?;
    let startup = runtime
        .as_ref()
        .map(lua::LuaRuntime::root_settings)
        .transpose()?
        .unwrap_or_default();
    let namespace = runtime
        .as_ref()
        .map(|runtime| runtime.daemon_callback::<String>("namespace", &serde_json::Value::Null))
        .transpose()?
        .flatten()
        .unwrap_or_else(Plots::namespace);
    if namespace.is_empty() || namespace.contains('\0') {
        return Err("daemon.namespace must be nonempty and contain no NUL".into());
    }
    init_tracing(startup.tracing.as_deref());
    let connection = Connection::connect_to_env().unwrap_or_else(|e| {
        eprintln!(
            "riced: cannot connect to Wayland ({e:?}); \
             is WAYLAND_DISPLAY set and are you inside a Wayland session?"
        );
        std::process::exit(1);
    });
    let connection2 = connection.clone();

    let (shell_broadcast, shell_events) = iced_wayland_subscriber::shell::channel();
    let mut host = Plots::new(shell_events.clone());
    if let Some(runtime) = runtime.filter(lua::LuaRuntime::is_daemon) {
        host.apps
            .install_daemon(runtime, &framework::Project::installed())?;
    }
    let redraw = host.apps.redraw.clone();
    let host = std::cell::RefCell::new(Some(host));

    daemon(
        move || {
            host.borrow_mut()
                .take()
                .unwrap_or_else(|| Plots::new(shell_events.clone()))
        },
        move || namespace.clone(),
        Plots::update,
        Plots::view,
    )
    .title(shell::daemon::title)
    .subscription(Plots::subscription)
    .theme(shell::daemon::theme)
    .style(shell::daemon::style)
    .settings(Settings {
        id: (!startup.connection.id.is_empty()).then(|| startup.connection.id.clone()),
        layer_settings: startup.settings.layer(),
        antialiasing: startup.connection.antialiasing,
        default_text_size: iced::Pixels(
            if startup.connection.default_text_size.is_finite()
                && startup.connection.default_text_size > 0.0
            {
                startup.connection.default_text_size
            } else {
                16.0
            },
        ),
        keep_compositor_alive: startup.connection.keep_compositor_alive,
        with_connection: Some(connection2.into()),
        shell_broadcast,
        ..Default::default()
    })
    .redraw_scope(move |message| shell::daemon::redraw(&redraw, message))
    .run()
    .map_err(Into::into)
}

fn shell_runtime() -> Result<Option<lua::LuaRuntime>, Box<dyn std::error::Error>> {
    let project = framework::Project::installed();
    let entry = project.source("root");
    if !entry.is_file() {
        return Ok(None);
    }
    let mut runtime =
        lua::LuaRuntime::with_profile(lua::sandbox::Profile::Widget, config::component_files())?;
    runtime.set_app_root(&project.root)?;
    runtime.load_path(&entry)?;
    Ok(Some(runtime))
}

fn init_tracing(filter: Option<&str>) {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_filter(filter))
        .init();
    // usvg's generic attribute parser warns about valid `marker-*: none`
    // declarations, which third-party SVG icons use freely. The tree still
    // parses and rasterizes; keep the per-icon warning spam out of the log.
    let _ = tracing_log::LogTracer::builder()
        .ignore_crate("usvg::parser::svgtree")
        .init();
}

/// `RUST_LOG` stays the default; `tracing = "..."` in `shell.lua` overrides it.
fn tracing_filter(filter: Option<&str>) -> tracing_subscriber::EnvFilter {
    filter
        .and_then(
            |filter| match tracing_subscriber::EnvFilter::try_new(filter) {
                Ok(filter) => Some(filter),
                Err(error) => {
                    eprintln!("shell.lua: invalid tracing filter {filter:?}: {error}");
                    None
                }
            },
        )
        .or_else(|| tracing_subscriber::EnvFilter::try_from_default_env().ok())
        .unwrap_or_else(|| tracing_subscriber::EnvFilter::new("info"))
}

#[cfg(test)]
mod tests {
    #[test]
    fn tracing_filter_prefers_the_configured_filter() {
        assert!(
            super::tracing_filter(Some("riced=debug"))
                .to_string()
                .contains("riced=debug")
        );
    }

    #[test]
    fn invalid_tracing_filter_falls_back_without_panicking() {
        let _ = super::tracing_filter(Some("[not=valid"));
    }
}
